inbound.set-body:
@{
            // Read the incoming REST JSON body and extract orderId
            var body = context.Request.Body.As(preserveContent: true);
            var orderId = body["orderId"]?.ToString();

            // Build the GraphQL query string
            var graphqlQuery = @"
                query retrieveOrder($orderId: String) {
                    retrieveOrder(orderId: $orderId) {
                        id
                        pnrId
                        status
                        pricing {
                            total { value currencyCode }
                            base  { value currencyCode }
                            taxes { value currencyCode }
                        }
                        connections {
                            origin {
                                airportCode
                                airportName
                            }
                            destination {
                                airportCode
                                airportName
                            }
                            departureDateTime
                            arrivalDateTime
                            flightNumber
                            cabinType
                            status
                        }
                        passengers {
                            id
                            passengerTypeCode
                            identityDetails {
                                firstName
                                lastName
                                gender
                                dateOfBirth
                                title
                            }
                        }
                        services {
                            id
                            name
                            quantity
                            pricing {
                                total { value currencyCode }
                            }
                        }
                        seats {
                            passengerId
                            flightId
                            seatNumber
                            pricing {
                                total { value currencyCode }
                            }
                        }
                        eligibilities {
                            cancel
                            cancelAndRefund
                            change
                        }
                        paymentInfo {
                            paymentType
                            amount { value currencyCode }
                        }
                    }
                }";

            // Compose the full GraphQL request payload
            var graphqlPayload = new JObject(
                new JProperty("query", graphqlQuery),
                new JProperty("variables", new JObject(
                    new JProperty("orderId", orderId)
                ))
            );

            return graphqlPayload.ToString();
        }

outbound.set-body:
@{
            var response = context.Response.Body.As(preserveContent: true);
            var retrieveOrder = response["data"]?["retrieveOrder"];
            return retrieveOrder != null ? retrieveOrder.ToString() : response.ToString();
        }
